// Typed application IPC. Types come from Rust (`src/bindings`, generated by
// ts-rs); this module only names commands and events. Rust validates every
// request at the boundary; never bypass these wrappers with raw `invoke`.
import { invoke } from "@tauri-apps/api/core";
import { listen, type UnlistenFn } from "@tauri-apps/api/event";

import type { AppInfo } from "../bindings/AppInfo";
import type { CommandError } from "../bindings/CommandError";
import type { DocumentChanged } from "../bindings/DocumentChanged";
import type { DocumentEvent } from "../bindings/DocumentEvent";
import type { DocumentId } from "../bindings/DocumentId";
import type { DocumentInfo } from "../bindings/DocumentInfo";
import type { DocumentState } from "../bindings/DocumentState";
import type { EditOrigin } from "../bindings/EditOrigin";
import type { TransactionError } from "../bindings/TransactionError";
import type { TransactionOutcome } from "../bindings/TransactionOutcome";
import type { TransactionRequest } from "../bindings/TransactionRequest";

export const commands = {
  appInfo: () => invoke<AppInfo>("app_info"),

  documentList: () => invoke<DocumentInfo[]>("document_list"),
  documentState: (document: DocumentId) => invoke<DocumentState>("document_state", { document }),
  documentApply: (request: TransactionRequest) => invoke<TransactionOutcome>("document_apply", { request }),
  documentUndo: (document: DocumentId, origin: EditOrigin) =>
    invoke<DocumentChanged>("document_undo", { document, origin }),
  documentRedo: (document: DocumentId, origin: EditOrigin) =>
    invoke<DocumentChanged>("document_redo", { document, origin }),
};

export const events = {
  /** Every document event, in revision order per document. */
  documents: (handler: (event: DocumentEvent) => void): Promise<UnlistenFn> =>
    listen<DocumentEvent>("documents:event", (e) => handler(e.payload)),
  /** The frontend fell behind; re-read state of every attached document. */
  documentsResync: (handler: () => void): Promise<UnlistenFn> => listen("documents:resync", () => handler()),
};

export function isCommandError(value: unknown): value is CommandError {
  return typeof value === "object" && value !== null && "code" in value && "message" in value;
}

export function isTransactionError(value: unknown): value is TransactionError {
  return typeof value === "object" && value !== null && "kind" in value && !("code" in value);
}

/** Human-readable message for any command rejection. */
export function errorMessage(error: unknown): string {
  if (isCommandError(error)) return error.message;
  if (isTransactionError(error)) return `Document change rejected (${error.kind})`;
  if (error instanceof Error) return error.message;
  return String(error);
}

/** Client-generated identifier for transactions and other correlated requests. */
export function newId(prefix: string): string {
  return `${prefix}-${crypto.randomUUID()}`;
}
